import { BaseHandler } from "../response/base.js";
import { createSnapshot } from "../../../observability/simple-metrics/metrics-state.js";
import { snapshotRequestProfiles } from "../../../observability/request-profiler.js";
import { ResponseBuilder } from "../../../security/index.js";
import { HTTP_INTERNAL_SERVER_ERROR, HTTP_OK, PRIORITY_HIGH, } from "../../../utils/constants/index.js";
import { memoryUsage, uptime } from "../../../platform/compat/process.js";
import { createLocalControlAccessDeniedResponse, isTrustedLocalControlRequest, } from "../../../security/http/local-control-request.js";
export class MetricsHandler extends BaseHandler {
    #metrics;
    constructor(metricsRuntime = { snapshot: createSnapshot }) {
        super();
        this.#metrics = metricsRuntime;
    }
    metadata = {
        name: "MetricsHandler",
        priority: PRIORITY_HIGH,
        patterns: [{ pattern: "/_metrics", exact: true }],
        enabled: (ctx) => !!ctx.isLocalProject,
    };
    handle(req, ctx) {
        if (!ctx.isLocalProject)
            return Promise.resolve(this.continue());
        const { pathname } = new URL(req.url);
        if (pathname !== "/_metrics")
            return Promise.resolve(this.continue());
        if (!isTrustedLocalControlRequest(req)) {
            return Promise.resolve(this.respond(createLocalControlAccessDeniedResponse(req, "Metrics request rejected")));
        }
        const securityConfig = ctx.securityConfig ?? undefined;
        const corsConfig = ctx.securityConfig?.cors;
        try {
            const snap = this.#metrics.snapshot();
            const profiling = snapshotRequestProfiles();
            const memory = this.safeCall(memoryUsage);
            const uptimeValue = this.safeCall(uptime);
            const response = ResponseBuilder.json({ counters: snap, profiling, memory, uptime: uptimeValue }, req, { securityConfig, corsConfig, status: HTTP_OK });
            return Promise.resolve(this.respond(response));
        }
        catch (e) {
            this.logWarn("metrics failed", { error: this.getErrorMessage(e) });
            const response = ResponseBuilder.error(HTTP_INTERNAL_SERVER_ERROR, "Failed to gather metrics", req, { securityConfig, corsConfig });
            return Promise.resolve(this.respond(response));
        }
    }
    safeCall(fn, name) {
        try {
            return fn();
        }
        catch (error) {
            this.logWarn(`metrics ${name ?? "call"} failed`, {
                error: error instanceof Error ? error.message : String(error),
            });
            return undefined;
        }
    }
}
